const request = require('request');

const options = {
  method: 'GET',
  url: 'https://api.procore.com/rest/v2.0/companies/%7Bcompany_id%7D/projects/%7Bproject_id%7D/budget_views/%7Bbudget_view_id%7D/detail_rows',
  qs: {
    page: 'SOME_INTEGER_VALUE',
    per_page: 'SOME_INTEGER_VALUE',
    filters: 'SOME_ARRAY_VALUE',
    '\"snapshot_id\"': '\"23\"',
    '\"column_ids\"': '\"1\",\"2\"',
    '\"mode\"': '\"difference\"',
    source_snapshot_id: 'SOME_STRING_VALUE',
