var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Get,
    RequestUri = new Uri("https://api.procore.com/rest/v2.0/companies/%7Bcompany_id%7D/projects/%7Bproject_id%7D/budget_views/%7Bbudget_view_id%7D/detail_rows?page=SOME_INTEGER_VALUE&per_page=SOME_INTEGER_VALUE&filters=SOME_ARRAY_VALUE&%5C%22snapshot_id%5C%22=%5C%2223%5C%22&%5C%22column_ids%5C%22=%5C%221%5C%22%2C%5C%222%5C%22&%5C%22mode%5C%22=%5C%22difference%5C%22&source_snapshot_id=SOME_STRING_VALUE&column_ids=SOME_ARRAY_VALUE"),
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}
